   416→/**
   417→ * Check for and handle any triggered crisis points
   418→ * Returns events generated by crisis choices
   419→ */
   420→export function processCrisisPoints(
   421→  state: GameState,
   422→  random: () => number = Math.random
   423→): {
   424→  newState: GameState;
   425→  events: GameEvent[];
   426→  crisisTriggered: boolean;
   427→} {
   428→  let currentState = { ...state };
   429→  const events: GameEvent[] = [];
   430→  let crisisTriggered = false;
   431→  
   432→  for (const crisis of ALL_CRISIS_POINTS) {
   433→    if (crisis.triggerCondition(currentState) && !crisis.triggered) {
   434→      crisisTriggered = true;
   435→      crisis.triggered = true;
   436→      
