   438→      const weights = crisis.options.map(opt => opt.weight(currentState));
   439→      const totalWeight = weights.reduce((sum, w) => sum + w, 0);
   440→      
   441→      // Randomly select an option based on weights
   442→      let randomValue = random() * totalWeight;
   443→      let selectedOption = crisis.options[0];
   444→      
   445→      for (let i = 0; i < crisis.options.length; i++) {
   446→        randomValue -= weights[i];
   447→        if (randomValue <= 0) {
   448→          selectedOption = crisis.options[i];
   449→          break;
   450→        }
   451→      }
   452→      
   453→      // Apply the consequence
   454→      const consequence = selectedOption.consequence(currentState);
   455→      currentState = {
   456→        ...currentState,
   457→        ...consequence
   458→      };
   459→      
