   471→          dystopia_shift: selectedOption.outcomeShift.dystopiaChange,
   472→          extinction_shift: selectedOption.outcomeShift.extinctionChange
   473→        }
   474→      });
   475→      
   476→      // Only process one crisis per step
   477→      break;
   478→    }
   479→  }
   480→  
   481→  return {
   482→    newState: currentState,
   483→    events,
   484→    crisisTriggered
   485→  };
   486→}
   487→
   488→/**
   489→ * Reset crisis points for a new simulation run
   490→ */
   491→export function resetCrisisPoints(): void {
   492→  ALL_CRISIS_POINTS.forEach(crisis => {
   493→    crisis.triggered = false;
   494→  });
   495→}
